import 'package:flutter/material.dart';

class ScanQrScreen extends StatefulWidget { const ScanQrScreen({super.key}); @override State<ScanQrScreen> createState()=>_ScanState(); }
class _ScanState extends State<ScanQrScreen> { int step=0; @override Widget build(BuildContext c)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:500),child:Column(children:[Text('Демонстраційне сканування',style:Theme.of(c).textTheme.headlineSmall!.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:6),Text('Приєднання учня до класу за QR-кодом'),const SizedBox(height:24),Container(height:280,width:280,decoration:BoxDecoration(color:Theme.of(c).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(24),border:Border.all(color:Theme.of(c).colorScheme.primary,width:2)),child:Center(child:Icon(step==0?Icons.qr_code_scanner:Icons.check_circle,size:80,color:step==2?Theme.of(c).colorScheme.secondary:Theme.of(c).colorScheme.primary))),const SizedBox(height:18),Text(step==0?'Наведено камеру на QR (демо)':step==1?'Знайдено: Дмитро • 8-Б':'✓ Дмитро доданий до 8-Б'),const SizedBox(height:14),FilledButton(onPressed:()=>setState(()=>step=step==2?0:step+1),child:Text(step==0?'Імітувати сканування':step==1?'Додати до класу':'Сканувати ще раз'))])))));}
